    if (graph == null) {
        throw new IllegalArgumentException("Input graph cannot be null");
    }

    // Create a new empty graph of the same type as the input graph
    Graph<V, E> identityGraph = new Graph<>(graph.getClass());

    // Add all the vertices of the input graph to the identity graph
    for (V vertex : graph.vertices()) {
        identityGraph.addVertex(vertex);
    }

    // Add all the edges of the input graph to the identity graph
    for (E edge : graph.edges()) {
        identityGraph.addEdge(edge);
    }

    // Create a mapping from the input graph to the identity graph
    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<>(graph, identityGraph);

    // Return the mapping
    return mapping;
}

