public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Validate input parameters
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    // Calculate the size of the message
    int size = schema.getMessageSize(message);

    // Serialize the message
    ByteArrayOutputStream bos = new ByteArrayOutputStream();
    CodedOutputStream cos = CodedOutputStream.newInstance(bos);
    schema.writeTo(cos, message);
    cos.flush();
    byte[] bytes = bos.toByteArray();

    // Prefix the message with its length
    ByteBuffer lengthBuffer = ByteBuffer.allocate(4);
    lengthBuffer.putInt(size);
    byte[] lengthBytes = lengthBuffer.array();
    out.write(lengthBytes);

    // Write the message to the output stream
    out.write(bytes);

    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
	int size = 0;
	// Serialize the message with the schema
	try {
		size = schema.writeTo(message, buffer);
		if (size == 0) {
		    throw new IllegalArgumentException("Message must not be empty");
		}
	} catch (SchemaException e) {
		throw new IOException(e);
	}
	// Prefix the message with its length
	out.write(new byte[size]);
	out.write(buffer.toByteArray());
	return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {

    // Calculate the size of the message
    int messageSize = schema.getSerializedSize(message, buffer);

    // Write the size of the message as a varint to the output stream
    CodedOutputStream codedOut = CodedOutputStream.newInstance(out);
    codedOut.writeRawVarint32(messageSize);

    // Serialize the message to the output stream using the schema
    schema.writeTo(codedOut, message);

    // Return the size of the message
    return messageSize;
}

@Override
public int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // 1. Handle null input
    if (message == null) {
        return 0;
    }

    // 2. Serialize the message with the given schema
    LinkedBuffer linkedBuffer = buffer == null ? LinkedBuffer.allocate() : buffer;
    int messageSize = schema.getSerializedSize(message, linkedBuffer);

    // 3. Prefix the message size to the output stream
    ByteWriter byteWriter = new ByteWriter(out);
    byteWriter.writeVarInt32(messageSize);

    // 4. Write the serialized message to the output stream
    schema.writeTo(message, linkedBuffer, out);
    return messageSize;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    LinkedBuffer linkedBuffer = buffer != null ? buffer : LinkedBuffer.allocate();
    try {
        return writeDelimitedToInternal(out, message, schema, linkedBuffer);
    } finally {
        linkedBuffer.clear();
    }
}

public static <T> int writeDelimitedToInternal(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Serialize the message to a buffer
    byte[] bytes = schema.writeToBuffer(message, buffer).array();
    // Write the length of the message as a varint
    ProtobufWriter.writeRawVarint32(bytes.length, out);
    // Write the message to the output stream
    out.write(bytes);
    // Return the size of the message
    return bytes.length + 4; // 4 is the size of the length varint
}

