public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {

// Step 1: Get the type variables for the target type
TypeVariable<?>[] typeVars = targetType.getTypeVariables();

// Step 2: Get the type arguments for the generic type
Type[] typeArgs = genericType.getActualTypeArguments();

// Step 3: Match the type arguments with the type variables
Map<TypeVariable<?>, Type> matching = new HashMap<>();
for (int i = 0; i < typeArgs.length; i++) {
matching.put(typeVars[i], typeArgs[i]);
}

// Step 4: Resolve the type arguments for the generic type
Class<?>[] resolvedArgs = new Class<?>[typeArgs.length];
for (int i = 0; i < typeArgs.length; i++) {
Type t = typeArgs[i];
if (t instanceof Class) {
resolvedArgs[i] = (Class<?>) t;
} else if (t instanceof TypeVariable) {
TypeVariable<?> tv = (TypeVariable<?>) t;
resolvedArgs[i] = (Class<?>) matching.get(tv);
} else {
throw new IllegalStateException("Illegal type argument: " + t);
}
}
return resolvedArgs;
}

