void insertBefore(Bucket bucket) {
  // Check if the given bucket is not null
  if (bucket == null) {
    throw new IllegalArgumentException("Cannot insert after a null bucket");
  }

  // Check if this bucket is not already inserted
  if (this.isInserted()) {
    throw new IllegalStateException("This bucket is already inserted");
  }

  // Check if the given bucket is not already inserted
  if (bucket.isInserted()) {
    throw new IllegalStateException("The given bucket is already inserted");
  }

  // Find the bucket before the given bucket
  Bucket previousBucket = bucket.getNext();

  // Insert this bucket between the previous bucket and the given bucket
  this.previous = previousBucket;
  this.next = bucket;
  previousBucket.next = this;
  bucket.previous = this;

  // Set the isInserted flag to true
  this.isInserted = true;
}

void insertBefore(Bucket bucket) {
    if (bucket == null) {
        throw new IllegalArgumentException("Cannot insert before null bucket");
    }
    if (this.next == null) {
        this.next = bucket;
        bucket.prev = this;
    } else {
        this.next.insertBefore(bucket);
    }
}

void insertBefore(Bucket bucket) {
    if (bucket == null) {
      throw new IllegalArgumentException("Cannot insert this bucket before null");
    }
    if (this.opposite == bucket) {
      throw new IllegalArgumentException("Cannot insert this bucket before its opposite");
    }
    if (this.opposite == null) {
      this.opposite = bucket;
      bucket.opposite = this;
      return;
    }
    Bucket current = this.opposite;
    while (current.opposite != null) {
      if (current.opposite == bucket) {
        break;
      }
      current = current.opposite;
    }
    if (current.opposite != null) {
      throw new IllegalStateException("Bucket is already part of another bucket");
    }
    current.opposite = bucket;
    bucket.opposite = current;
  }

