    String value = props.getProperty(key);
    if (value == null) {
        throw new IllegalArgumentException("Key not found: " + key);
    }
    return substituteVariables(value, props);
}

private static String substituteVariables(String value, Properties props) {
    Pattern pattern = Pattern.compile("\\$\\{([A-Za-z0-9_.]+)\\}");
    Matcher matcher = pattern.matcher(value);
    StringBuffer buffer = new StringBuffer();
    while (matcher.find()) {
        String replacement = props.getProperty(matcher.group(1));
        if (replacement == null) {
            replacement = matcher.group(0);
        }
        matcher.appendReplacement(buffer, replacement);
    }
    matcher.appendTail(buffer);
    return buffer.toString();
}

public static String findAndSubst(String key, Properties props) {
    // Step 1: Check if the key exists in the Properties
    if (!props.containsKey(key)) {
        return null;
    }

    // Step 2: Get the value corresponding to the key
    String value = props.getProperty(key);

    // Step 3: Perform variable substitution on the value
    value = substituteVariables(value, props);

    return value;
}

private static String substituteVariables(String input, Properties props) {
    // Step 1: Find all variables in the input string
    List<String> variables = getVariables(input);

    // Step 2: Substitute the variables with the values from the Properties object
    for (String variable : variables) {
        String value = props.getProperty(variable);
        if (value != null) {
            input = input.replace("${" + variable + "}", value);
        }
    }

    return input;
}

private static List<String> getVariables(String input) {
    List<String> variables = new ArrayList<>();
    Pattern pattern = Pattern.compile("\\$\\{([^}]+)\\}");
    Matcher matcher = pattern.matcher(input);
    while (matcher.find()) {
        String variable = matcher.group(1);
        variables.add(variable);
    }
    return variables;
}

