public void valueAccumulation(String key, Long value) {
  /*
   * Check if the input is valid.
   */
  if (key == null || value == null) {
    throw new IllegalArgumentException("The input key and value cannot be null.");
  }

  /*
   * Get the existing value for the given key.
   */
  Long existingValue = values.get(key);

  /*
   * If there is no existing value, set the given value as the new value.
   */
  if (existingValue == null) {
    values.put(key, value);
  } else {
    /*
     * Otherwise, accumulate the existing value with the given value.
     */
    long newValue = existingValue + value;
    values.put(key, newValue);
  }
}

