    InputStream inputStream = new FileInputStream(nextFile);

    return inputStream;
}

public InputStream next() throws IOException {
    if (currentFileIndex >= files.size()) {
        return null;
    }
    File nextFile = files.get(currentFileIndex);
    currentFileIndex++;
    return new FileInputStream(nextFile);
}

public InputStream next() throws IOException {
    // If the current file is not null and has not been read completely, return it
    if (currentFile != null && !currentFile.isReadComplete()) {
        return currentFile;
    }

    // If there are no more files, return null
    if (files.isEmpty()) {
        return null;
    }

    // Otherwise, read the next file and return it
    currentFile = files.remove(0);
    currentFile.read();
    return currentFile;
}

public InputStream next() throws IOException {
    if (currentFile == null) {
        return null;
    }

    try {
        InputStream inputStream = new FileInputStream(currentFile);
        currentFile = getNextFile();
        return inputStream;
    } catch (FileNotFoundException e) {
        throw new IOException("File not found: " + currentFile.getName(), e);
    }
}

