    }
    for (int i = off; i < off + len; i++) {
        write(b[i]);
    }
}

public void write(final byte b[],final int off,final int len) throws IOException {
        if (b == null) {
            throw new NullPointerException("The input byte array is null");
        }
        if (off < 0 || off >= b.length) {
            throw new IndexOutOfBoundsException("The offset is out of bounds");
        }
        if (len < 0 || len > b.length - off) {
            throw new IndexOutOfBoundsException("The length is out of bounds");
        }
        for (int i = off; i < off + len; i++) {
            write(b[i]);
        }
    }

public void write(byte b[], int off, int len) throws IOException {
    if (b == null || off < 0 || len < 0 || len > b.length - off) {
        throw new IllegalArgumentException("Invalid parameters");
    }
    if (len == 0) {
        return;
    }
    if (closed) {
        throw new IOException("Stream closed");
    }
    writeQueue.add(Arrays.copyOfRange(b, off, off + len));
    writeQueue.add(null);
    while (writeQueue.peek() != null) {
        byte[] chunk = writeQueue.poll();
        if (chunk != null) {
            out.write(chunk);
        } else {
            break;
        }
    }
}

