public void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Check if the edge already exists in the index
    if (edgeIndex.containsKey(e)) {
        throw new IllegalArgumentException("Edge already exists in the index");
    }

    // Add the edge to the index
    edgeIndex.put(e, new HashSet<>());

    // Add the source and target vertex to the edge index
    HashSet<V> sourceVertices = edgeIndex.get(sourceVertex);
    if (sourceVertices == null) {
        sourceVertices = new HashSet<>();
        edgeIndex.put(sourceVertex, sourceVertices);
    }
    sourceVertices.add(e);

    HashSet<V> targetVertices = edgeIndex.get(targetVertex);
    if (targetVertices == null) {
        targetVertices = new HashSet<>();
        edgeIndex.put(targetVertex, targetVertices);
    }
    targetVertices.add(e);
}

