  Set<E> edges = new HashSet<>();
  for (V otherVertex : index.get(vertex)) {
    Set<E> otherEdges = index.get(otherVertex);
    if (otherEdges != null) {
      edges.addAll(otherEdges);
    }
  }
  return edges;
}

protected Set<E> getEdgesForTargets(V vertex) {
  Set<E> edges = new HashSet<>();
  for (V otherVertex : index.get(vertex)) {
    Set<E> otherEdges = index.get(otherVertex);
    if (otherEdges != null) {
      edges.addAll(otherEdges);
    }
  }
  return edges;
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Step 1: Check if the source and target vertices are valid
    if (sourceVertex == null || targetVertex == null) {
        throw new IllegalArgumentException("Source and target vertices must not be null");
    }

    // Step 2: Check if the edge is valid
    if (e == null) {
        throw new IllegalArgumentException("Edge must not be null");
    }

    // Step 3: Check if the edge already exists in the index
    if (index.containsKey(e)) {
        throw new IllegalArgumentException("Edge already exists in the index");
    }

    // Step 4: Add the edge to the index
    index.put(e, new HashSet<V>());
    index.get(e).add(sourceVertex);
    index.get(e).add(targetVertex);
}

