public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box.isEmpty()) {
        return Pair.empty();
    }
    double centerX = (box.x_min + box.x_max) / 2;
    Box2D box1 = new Box2D(box.x_min, centerX, box.y_min, box.y_max);
    Box2D box2 = new Box2D(centerX, box.x_max, box.y_min, box.y_max);
    return Pair.of(box1, box2);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("Box must not be null");
    }
    double width = box.getWidth();
    if (width <= 0) {
        throw new IllegalArgumentException("Box width must be positive");
    }
    double height = box.getHeight();
    if (height <= 0) {
        throw new IllegalArgumentException("Box height must be positive");
    }
    double xMidpoint = box.getX() + (width / 2);
    Box2D leftBox = new Box2D(box.getX(), box.getY(), xMidpoint, height);
    Box2D rightBox = new Box2D(xMidpoint, box.getY(), box.getMaxX(), height);
    return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("Box2D cannot be null");
    }
    double centerX = box.getCenterX();
    double halfWidth = box.getWidth() / 2.0;
    Box2D leftBox = new Box2D(centerX - halfWidth, box.getCenterY(), centerX - halfWidth, box.getHeight());
    Box2D rightBox = new Box2D(centerX + halfWidth, box.getCenterY(), centerX + halfWidth, box.getHeight());
    return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    // calculate the midpoint of the box along the x axis
    double midpoint = (box.getX() + box.getX() + box.getWidth()) / 2.0;

    // create two new boxes with the same height and depth as the input box, but with different widths and positions
    Box2D box1 = new Box2D(box.getX(), box.getY(), midpoint - box.getX(), box.getHeight(), box.getDepth());
    Box2D box2 = new Box2D(midpoint, box.getY(), box.getX() + box.getWidth() - midpoint, box.getHeight(), box.getDepth());

    return new Pair<Box2D,Box2D>(box1, box2);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }
    if (box.getWidth() == 0) {
        throw new IllegalArgumentException("Box must have non-zero width");
    }
    double halfWidth = box.getWidth() / 2;
    Box2D box1 = new Box2D(box.getMinX(), box.getMinY(), halfWidth, box.getHeight());
    Box2D box2 = new Box2D(box.getMinX() + halfWidth, box.getMinY(), halfWidth, box.getHeight());
    return new Pair<>(box1, box2);
}

