public int compare(Double o1, Double o2) {
    if (o1 == null && o2 == null) {
        return 0;
    } else if (o1 == null) {
        return -1;
    } else if (o2 == null) {
        return 1;
    } else {
        return Double.compare(o1, o2);
    }
}

@Override
public int compare(Double o1, Double o2) {
    // Handle null values
    if (o1 == null || o2 == null) {
        throw new IllegalArgumentException("Cannot compare null values");
    }

    // Compare floating point values using Math.ulp
    if (Math.abs(o1 - o2) <= Math.max(Math.ulp(o1), Math.ulp(o2))) {
        return 0;
    } else if (o1 < o2) {
        return -1;
    } else {
        return 1;
    }
}

