    // Step 1: Convert the input arguments to their primitive types to avoid unexpected behavior
    double d1 = o1.doubleValue();
    double d2 = o2.doubleValue();

    // Step 2: Compare the values using the conditional operators
    if (d1 < d2) {
        return -1;
    } else if (d1 > d2) {
        return 1;
    } else {
        return 0;
    }
}

