public static int nextPrime(int desiredCapacity) {
  // Step 1: Check for invalid inputs
  if (desiredCapacity < 0) {
    throw new IllegalArgumentException("Desired capacity must be a positive integer.");
  }

  // Step 2: Find the next prime number greater than or equal to the desired capacity
  double approximateCapacity = desiredCapacity * 1.11; // 11% higher than desired capacity
  while (!isPrime(approximateCapacity)) {
    approximateCapacity += 1;
  }

  // Step 3: Return the prime number if it is within 11% of the desired capacity
  if (Math.abs(approximateCapacity - desiredCapacity) / desiredCapacity <= 0.11) {
    return (int) approximateCapacity;
  }

  // Step 4: Otherwise, return the next prime number greater than the desired capacity
  return (int) approximateCapacity + 1;
}

