public final byte[] toByteArray() {
    /* Step 1: Check if the buffer is empty */
    if (buffer.size() == 0) {
        return new byte[0];
    }

    /* Step 2: Calculate the total length of the buffer */
    int totalLength = 0;
    for (ByteBuffer buffer : buffers) {
        totalLength += buffer.capacity();
    }

    /* Step 3: Allocate a new byte array of the total length */
    byte[] result = new byte[totalLength];

    /* Step 4: Copy each buffer's contents into the byte array */
    int offset = 0;
    for (ByteBuffer buffer : buffers) {
        buffer.flip();
        buffer.get(result, offset, buffer.limit());
        offset += buffer.limit();
        buffer.clear();
    }

    return result;
}

public final byte[] toByteArray() {
    List<Byte> byteList = new ArrayList<>();
    for (ByteBuffer buffer : buffers) {
        int limit = buffer.limit();
        for (int i = 0; i < limit; i++) {
            byteList.add(buffer.get());
        }
    }
    byte[] byteArray = new byte[byteList.size()];
    for (int i = 0; i < byteArray.length; i++) {
        byteArray[i] = byteList.get(i);
    }
    return byteArray;
}

public byte[] toByteArray() {
    byte[] result = new byte[size()];
    int offset = 0;

    for (List<Byte> buffer : buffers) {
        for (byte b : buffer) {
            result[offset++] = b;
        }
    }

    return result;
}

public final byte[] toByteArray() {
  // Initialize an empty byte array to hold the contents of all buffers
  byte[] result = new byte[0];

  // Iterate through each buffer in the chain
  for (Buffer buffer : buffers) {
    // If the buffer is not empty, concatenate its contents to the result array
    if (buffer.position() > 0) {
      result = Arrays.copyOf(result, result.length + buffer.position());
      buffer.get(result, result.length - buffer.position(), buffer.position());
    }
  }

  return result;
}

