    if (bufferList.isEmpty()) {
        return new byte[0];
    }

    // Step 2: Calculate the total size of the buffer
    int totalSize = 0;
    for (ByteBuffer buffer : bufferList) {
        totalSize += buffer.remaining();
    }

    // Step 3: Allocate a new byte array of the total size
    byte[] result = new byte[totalSize];

    // Step 4: Copy the contents of each buffer into the new byte array
    int offset = 0;
    for (ByteBuffer buffer : bufferList) {
        while (buffer.hasRemaining()) {
            result[offset] = buffer.get();
            offset++;
        }
    }

    return result;
}

