public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder unescaped = new StringBuilder(str.length());
    boolean modified = false;
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            i++;
            if (i < str.length()) {
                c = str.charAt(i);
                switch (c) {
                    case '\\':
                        unescaped.append('\\');
                        break;
                    case 'n':
                        unescaped.append('\n');
                        break;
                    case 't':
                        unescaped.append('\t');
                        break;
                    case 'r':
                        unescaped.append('\r');
                        break;
                    case '\'':
                        unescaped.append('\'');
                        break;
                    case '\"':
                        unescaped.append('\"');
                        break;
                    default:
                        throw new Exception("Illegal escape sequence '\\" + c + "'");
                }
                modified = true;
            } else {
                // Trailing '\' is an invalid sequence and will be handled below
                break;
            }
        } else {
            unescaped.append(c);
        }
    }
    // Check for trailing '\' character
    if (modified && str.charAt(str.length() - 1) == '\\') {
        throw new Exception("Trailing '\' character");
    }
    return unescaped.toString();
}

