private static String javaCharset(String charset) throws UnsupportedCharsetException {
  // Step 1: Validate the input charset name
  if(!Charset.isSupported(charset)){
    throw new UnsupportedCharsetException("Charset " + charset + " is not supported.");
  }
  // Step 2: Get the available Java Charsets
  Charset[] availableCharsets = Charset.availableCharsets();
  // Step 3: Find the Java Charset that matches the MIME charset
  for(Charset availableCharset : availableCharsets){
    if(availableCharset.getMimeType().equalsIgnoreCase(charset)){
      return availableCharset.getName();
    }
  }
  throw new UnsupportedCharsetException("No Java Charset found for MIME charset " + charset + ".");
}

