protected Object filter(Object msg) {
    // Check if the message is null
    if (msg == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }

    // Check if the message is a String
    if (!(msg instanceof String)) {
        throw new IllegalArgumentException("Message must be a String");
    }

    // Invoke the BroadcastFilter
    Object result = BroadcastFilter.filter(msg);

    // Check if the result is null
    if (result == null) {
        throw new RuntimeException("BroadcastFilter returned null");
    }

    // Check if the result is a String
    if (!(result instanceof String)) {
        throw new RuntimeException("BroadcastFilter returned a non-String value");
    }

    return result;
}

