  }

  // Check if byteOffset and byteLength are valid
  if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
    throw new IndexOutOfBoundsException("Invalid byte offset: " + byteOffset);
  }
  if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
    throw new IndexOutOfBoundsException("Invalid byte length: " + byteLength);
  }

  // Enlarge the byte vector if necessary
  ensureCapacity(byteLength);

  // Copy the bytes from the input array to the byte vector
  for (int i = 0; i < byteLength; i++) {
