        return null;
    }
    MatchResult result = new MatchResult(this);
    for(int i = 0; i < uri.length(); i++){
        CharArraySequence charSequence = new CharArraySequence(uri.subSequence(i, uri.length()));
        MatchResult candidateResult = new MatchResult(this);
        for(Template pattern : this.patterns){
            MatchResult patternResult = pattern.match(charSequence, candidateResult);
            if(patternResult != null){
                candidateResult = patternResult;
                break;
            }
        }
        if(candidateResult.isFullMatch()){
            result = candidateResult;
            break;
        }
    }
    return result;
}

