    if (uri == null || uri.length() == 0) {
        return null;
    }

    try {
        String uriString = uri.toString();
        URI uriObj = new URI(uriString);
        String uriPattern = uriObj.getScheme() + "://" + uriObj.getAuthority() + "/" + uriObj.getPath();

        if (!this.pattern.matcher(uriPattern).matches()) {
            return null;
        }

        Map<String, String> params = new HashMap<>();
        int paramCount = this.namedGroupNames.size();
        Matcher matcher = this.pattern.matcher(uriPattern);
        while (matcher.find()) {
            String groupName = matcher.group(1);
            String groupValue = matcher.group(2);
            params.put(groupName, groupValue);
        }

        return new MatchResult(params, uriPattern);
    } catch (URISyntaxException e) {
        return null;
    }
}

