  // Loop through each edge entering the vertex
  for (Edge<V, E> edge : v.getEdges()) {
    // Get the weight of the edge
    double weight = edge.getWeight();

    // Check if the weight is valid
    if (weight >= 0) {
      // Increment the sum by the weight
      sum += weight;
    } else {
      // Throw an exception if the weight is negative
      throw new IllegalArgumentException("Edge weight must be non-negative.");
    }
  }

  // Return the sum of the weights
  return sum;
}

