protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    GraphPath<V,E> result = new GraphPath<V,E>(graph);
    if(tour.isEmpty()){
        return result;
    } else {
        result.addEdge(tour.get(0));
        if(tour.size() > 1){
            //check if the last edge in the tour is connected to the first edge
            if(graph.getEdge(tour.get(tour.size()-1),tour.get(0)) != null){
                result.addEdge(tour.get(tour.size()-1));
            }
        }
    }
    return result;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
if(tour == null){
throw new IllegalArgumentException("Tour must not be null");
}
if(graph == null){
throw new IllegalArgumentException("Graph must not be null");
}
GraphPath<V,E> path = new GraphPath<V,E>();
path.setVertex(tour.getVertexByIndex(0));
for(int i = 1; i < tour.size(); i++){
V u = path.getEnd();
V v = tour.getVertexByIndex(i);
Edge<E> e = graph.getEdge(u,v);
path.addEdge(e);
path.setVertex(v);
}
return path;
}

// Check if the tour set is empty
if (tour.isEmpty()) {
    throw new IllegalArgumentException("Tour set is empty");
}

// Get the start vertex and add it to the graph path
V startVertex = getStartVertex(graph);
GraphPath<V, E> path = new GraphPath<>(graph, startVertex);

// Iterate over the tour set and add each edge to the graph path
for (E edge : tour) {
    V sourceVertex = graph.getEdgeSource(edge);
    V targetVertex = graph.getEdgeTarget(edge);
    if (!path.containsVertex(sourceVertex)) {
        path.addEdge(edge, sourceVertex, targetVertex);
    }
}

// Return the graph path
return path;

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty() || graph == null || graph.isEmpty()) {
        throw new IllegalArgumentException("Invalid input: tour or graph is null or empty");
    }
    GraphPath<V,E> path = new GraphPath<V,E>();
    for (E edge : tour) {
        if (!graph.containsEdge(edge)) {
            throw new IllegalArgumentException("Graph does not contain edge " + edge);
        }
        path.addEdge(edge);
    }
    return path;
}

