public int addConstantNameAndType(final String name, final String descriptor) {
    if (constantPool.contains(name, descriptor)) {
        return constantPool.nameAndType(name, descriptor);
    }
    int tag = name.startsWith("<") ? CG_TAG_FIELD_ID : 
    CG_TAG_METHOD_ID;
    Symbol sym = new Symbol(name, tag);
    sym.setType(descriptor);
    constantPool.add(sym);
    return sym;
}

public int addConstantNameAndType(final String name, final String descriptor) {
  // Check if the constant pool already contains a similar item
  for (int i = 0; i < constantPool.size(); i++) {
    Symbol symbol = constantPool.get(i);
    if (symbol.name.equals(name) && symbol.descriptor.equals(descriptor)) {
      return i;
    }
  }

  // If not, create a new entry for the constant pool
  Symbol symbol = new Symbol(name, descriptor);
  constantPool.add(symbol);
  return constantPool.size() - 1;
}

public Symbol addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new NullPointerException("Name and descriptor cannot be null");
    }
    if (name.isEmpty()) {
        throw new IllegalArgumentException("Name cannot be empty");
    }
    if (!descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be empty");
    }
    Symbol symbol = new Symbol();
    symbol.setName(name);
    symbol.setDescriptor(descriptor);
    this.constantPool.put(symbol.toString(), symbol);
    return symbol;
}

public int addConstantNameAndType(final String name, final String descriptor) {
    // Step 1: Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPool.size(); i++) {
        CstRef cstRef = (CstRef) constantPool.get(i);
        if (cstRef.name.equals(name) && cstRef.descriptor.equals(descriptor)) {
            // If a similar item is found, return its index
            return i;
        }
    }

    // Step 2: Add a new item to the constant pool
    CstRef cstRef = new CstRef(name, descriptor);
    constantPool.add(cstRef);
    return constantPool.size() - 1;
}

int addConstantNameAndType(final String name, final String descriptor) {
  // Check if the constant pool already contains a similar item
  for (Symbol sym : constantPool) {
    if (sym.type == Symbol.CONSTANT_NameAndType && sym.name.equals(name) && sym.descriptor.equals(descriptor)) {
      return sym.index; // Already exists, return the index
    }
  }

  // If not, create a new Symbol with the given name and descriptor
  Symbol sym = new Symbol(Symbol.CONSTANT_NameAndType, name, descriptor);
  constantPool.add(sym);
  return sym.index; // Return the index of the new Symbol
}

