public void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Step 1: Move all vertices from the bucket with label minLabel to the bucket with label 0
    Set<Integer> verticesToMove = bucketsByLabel.get(minLabel);
    for (Integer vertex : verticesToMove) {
        labels.set(vertex, 0);
        bucketsByLabel.get(0).add(vertex);
        bucketsByLabel.get(minLabel).remove(vertex);
    }

    // Step 2: Clear the bucket with label minLabel
    bucketsByLabel.get(minLabel).clear();

    // Step 3: Update the labeling accordingly
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        if (i != minLabel) {
            Set<Integer> verticesInBucket = bucketsByLabel.get(i);
            for (Integer vertex : verticesInBucket) {
                labels.set(vertex, i + 1);
            }
        }
    }
}

