            // if the character is a terminator, break out of the loop
            break;
        } else {
            // if the character is not a terminator, add it to the token
            token += ch;
        }
    }
    return token;
}

private String parseToken(final char[] terminators) {
    // Step 1: Initialize the token and index variables
    int index = 0;
    String token = "";

    // Step 2: Iterate through the input until we encounter a terminator or reach the end of the input
    for (char currentChar : terminators) {
        if (input.length() > index && !Character.isWhitespace(input.charAt(index))) {
            token += input.charAt(index);
            index++;
        }
    }

    // Step 3: Remove any leading or trailing whitespace from the token
    token = token.trim();

    // Step 4: Check if the token is empty and return the appropriate value
    if (token.isEmpty()) {
        return "";
    } else {
        return token;
    }
}

private String parseToken(final char[] terminators) {
    StringBuilder token = new StringBuilder();
    for (int i = 0; i < terminators.length; i++) {
        if (terminators[i] == currentChar) {
            return token.toString();
        } else {
            token.append(currentChar);
            currentChar = reader.read();
        }
    }
    return token.toString();
}

