private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) throws IllegalArgumentException {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Bounds list must not be null or empty.");
    }
    List<Integer> suffixSums = new ArrayList<>(bounds.size());
    long totalSum = 0;
    for (int i = 0; i < bounds.size(); i++) {
        Integer curr = bounds.get(i);
        if (curr == null) {
            throw new IllegalArgumentException("Bounds list must not contain null elements.");
        }
        if (curr < 0) {
            throw new IllegalArgumentException("Bounds list must only contain non-negative integers.");
        }
        suffixSums.add(curr);
        totalSum += curr;
    }
    return Pair.of(suffixSums, totalSum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Bounds list cannot be null or empty.");
    }

    List<Integer> suffixSums = new ArrayList<>(bounds.size());
    long sumOfAllElements = 0;

    for (int i = 0; i < bounds.size(); i++) {
        suffixSums.add(bounds.get(bounds.size() - 1 - i));
        sumOfAllElements += bounds.get(i);
    }

    return new Pair<>(suffixSums, sumOfAllElements);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // empty bounds list, return empty suffix sum and sum of all elements as 0
    if (bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }

    // initialize the suffix sum list and total sum
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;

    // iterate through the bounds list in reverse order
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // add the current element to the suffix sum list
        suffixSum.add(bounds.get(i));

        // add the current element to the total sum
        totalSum += bounds.get(i);
    }

    // return the computed suffix sum list and total sum
    return new Pair<>(suffixSum, totalSum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
	if(bounds == null || bounds.isEmpty()){
		return new Pair<>(Collections.emptyList(),0L);
	}
	List<Integer> suffixSum = new ArrayList<>(bounds.size());
	long sum = 0L;
	for(int i = bounds.size() - 1; i >= 0; i--){
		sum += bounds.get(i);
		suffixSum.add(sum);
	}
	return new Pair<>(suffixSum,sum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    int sum = 0;
    List<Integer> suffixSums = new ArrayList<>();
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSums.add(sum);
    }
    Collections.reverse(suffixSums);
    return Pair.of(suffixSums, sum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
  if (arr == null || arr.length == 0 || from < 0 || to < 0 || from >= arr.length || to >= arr.length) {
    throw new IllegalArgumentException("Invalid input");
  }

  int mid = (from + to) / 2;
  for (int i = from; i <= mid; i++) {
    int mirrorIndex = to - (i - from);
    V temp = arr[i];
    arr[i] = arr[mirrorIndex];
    arr[mirrorIndex] = temp;
  }
}

/**
 * Reverses the order of the elements in the specified range within the given array.
 * @param < V > the type of elements in the array
 * @param arr the array
 * @param from the index of the first element (inclusive) inside the range to reverse
 * @param to the index of the last element (inclusive) inside the range to reverse
 */
public static final <V>void reverse(V[] arr, int from, int to){
    if (arr == null) {
        throw new NullPointerException("The array cannot be null.");
    }

    if (from < 0 || from >= arr.length) {
        throw new IndexOutOfBoundsException("The start index must be a valid index in the array.");
    }

    if (to < 0 || to >= arr.length) {
        throw new IndexOutOfBoundsException("The end index must be a valid index in the array.");
    }

    if (from > to) {
        throw new IndexOutOfBoundsException("The start index must be less than or equal to the end index.");
    }

    int temp;
    for (int i = from, j = to; i < j; i++, j--) {
        temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("The array cannot be null");
    }
    if (from < 0 || to < 0 || from >= arr.length || to >= arr.length) {
        throw new IllegalArgumentException("The from and to indices must be in the range of the array");
    }
    if (from > to) {
        throw new IllegalArgumentException("The from index must be less than or equal to the to index");
    }

    int length = to - from + 1;
    int mid = (length / 2) - 1;
    for (int i = 0; i < mid; i++) {
        V temp = arr[from + i];
        arr[from + i] = arr[to - i];
        arr[to - i] = temp;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
  if (arr == null || arr.length == 0) {
    throw new IllegalArgumentException("The array cannot be null or empty");
  }
  if (from < 0 || to < 0 || from >= arr.length || to >= arr.length) {
    throw new IndexOutOfBoundsException("The from and to indices must be within the bounds of the array");
  }
  if (from > to) {
    throw new IllegalArgumentException("The from index must be less than or equal to the to index");
  }

  int i = from;
  int j = to;
  while (i < j) {
    V temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
    i++;
    j--;
  }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    Objects.requireNonNull(arr);
    int n = to - from + 1;
    if (n <= 0 || n > arr.length) {
        throw new IllegalArgumentException("Invalid range specified");
    }
    for (int i = from; i <= to; i++) {
        int j = to - i + from;
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

