        // Check if the given BeanMap is null
        if (map == null) {
            throw new NullPointerException("Given BeanMap is null");
        }

        // Iterate over the given BeanMap's entries and put only the writable properties into this BeanMap
        for (Map.Entry<String, Object> entry : map.entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();
            try {
                // Check if the property is writable
                if (getWriteMethod(key) == null) {
                    continue;
                }

                // Put the writable property into this BeanMap
                put(key, value);
            } catch (IntrospectionException e) {
                // Catch the IntrospectionException and ignore it
                // This means that the property is not writable
            }
        }
    }

