  // check if the input BeanMap is valid
  if (map == null) {
    throw new IllegalArgumentException("The input BeanMap must not be null");
  }

  // iterate through the properties in the input BeanMap
  for (String propertyName : map.getPropertyNames()) {
    // check if the property is writable
    if (map.isWritable(propertyName)) {
      // get the property value from the input BeanMap
      Object value = map.get(propertyName);

      // put the property and value into this BeanMap
      put(propertyName, value);
    }
  }
}

