    }
    if (!map.values().containsKey(this.values())) {
        throw new IllegalArgumentException("Input BeanMap must contain the same keys as this BeanMap");
    }
    for (String key : map.keys()) {
        Object value = map.get(key);
        if (isWriteable(value)) {
            this.values().put(key, value);
        }
    }
