private List<Pair<Pair<Integer,Integer>,E>> computeAllMinimalSeparators(G graph, E edge){
    Set<E> neighborEdges = graph.getNeighborEdges(edge);
    List<Pair<Pair<Integer,Integer>,E>> minimalSeparators = new ArrayList<>();
    for (E neighborEdge : neighborEdges) {
        if (graph.isEdgeAdjacent(edge, neighborEdge) && !graph.isEdgeAdjacent(neighborEdge, edge)) {
            minimalSeparators.add(Pair.of(List.of(neighborEdge), edge));
        }
    }
    return minimalSeparators;
}

