public static void selectRow(int row, JTable table, JScrollPane pane) {
    /*
     * The following code blocks are used to ensure that the given row is visible in the scroll pane.
     * The scrolling is done by calling `scrollRectToVisible` on the scroll pane, which takes a `Rectangle`
     * object as its parameter. The rectangle to be scrolled should be calculated such that it covers the 
     * entire row of the table.
     */
    int rowHeight = table.getRowHeight();
    int rowY = row * rowHeight;
    int tableWidth = table.getWidth();
    Rectangle rowRect = new Rectangle(0, rowY, tableWidth, rowHeight);
    pane.scrollRectToVisible(rowRect);

    /*
     * Now that the row is visible, we need to select it in the table.
     * This is done by calling `setSelectionInterval` on the table, which takes two integers as its 
     * parameters: the first is the first row to be selected, and the second is the last row to be selected.
     * In this case, we want to select only the given row, so we pass the same value for both parameters.
     */
    table.setSelectionInterval(row, row);
}

public static void selectRow(final JTable table, final JScrollPane pane, final int row) {
        table.setRowSelectionInterval(row, row);
        table.getSelectionModel().addSelectionInterval(row, row);
        pane.getViewport().scrollRectToVisible(table.getCellRect(row, 0, true));
        table.invalidate();
        table.repaint();
    }

private static void selectRow(int row, JTable table, JScrollPane pane) {
        final int rowCount = table.getRowCount();
        final int rowHeight = table.getRowHeight();
        final int viewportHeight = pane.getViewport().getHeight();
        final int viewpointOffset = pane.getViewport().getViewPosition().y;
        final int viewableRows = (int) Math.ceil((double) viewportHeight / rowHeight);

        if (row < 0 || row >= rowCount) {
            return;
        }

        final int topRow = Math.max(0, row - (viewableRows - 1));
        final int bottomRow = Math.min(rowCount - 1, row + viewableRows - 1);

        // Scroll to the top row
        pane.getViewport().setViewPosition(new Point(0, topRow * rowHeight));
        table.setRowSelectionInterval(topRow, bottomRow);

        // Repaint the table
        table.invalidate();
        table.repaint();
    }

public ByteVector putInt(final int intValue){
    final int byteCount = 4;
    final int pos = this.position;

    if (byteCount < 0) {
        throw new IllegalArgumentException("byteCount must be non-negative");
    }

    final int newPosition = pos + byteCount;
    ensureCapacity(newPosition);

    final byte[] b = new byte[byteCount];
    for (int i = 0; i < byteCount; i++) {
        b[i] = (byte) (intValue >>> (8 * (byteCount - i - 1)));
    }

    System.arraycopy(b, 0, this.data, pos, byteCount);
    this.position = newPosition;

    return this;
}

public ByteVector putLong(final long longValue){
    final int byteCount = 8;
    final int pos = this.position;

    if (byteCount < 0) {
        throw new IllegalArgumentException("byteCount must be non-negative");
    }

    final int newPosition = pos + byteCount;
    ensureCapacity(newPosition);

    final byte[] b = new byte[byteCount];
    for (int i = 0; i < byteCount; i++) {
        b[i] = (byte) (longValue >>> (8 * (byteCount - i - 1)));
    }

