}

public ByteVector putInt(final int intValue) {
	// Check if the ByteVector needs to be enlarged
	if (intValue > this.buf.length - this.len) {
		// Enlarge the ByteVector to ensure enough space for the int
		byte[] newBuf = new byte[this.buf.length + Math.max(intValue, 10)];
		System.arraycopy(this.buf, 0, newBuf, 0, this.len);
		this.buf = newBuf;
	}

	// Put the int into the ByteVector
	this.buf[this.len++] = (byte) (intValue >>> 24);
	this.buf[this.len++] = (byte) (intValue >>> 16);
	this.buf[this.len++] = (byte) (intValue >>> 8);
	this.buf[this.len++] = (byte) intValue;

	return this;
}

public ByteVector putInt(final int intValue){
        if (this.data == null) {
            throw new NullPointerException("Data is null");
        }
        if (this.data.length - this.position < 4) {
            throw new IndexOutOfBoundsException("Insufficient space to put an int");
        }
        this.data[this.position++] = (byte) (intValue >> 24);
        this.data[this.position++] = (byte) (intValue >> 16);
        this.data[this.position++] = (byte) (intValue >> 8);
        this.data[this.position++] = (byte) intValue;
        return this;
    }

