}

public ByteVector putInt(final int intValue) throws IllegalArgumentException{

// Step 1: Check if the input integer is valid and within the limits of a byte vector
if (intValue < Byte.MIN_VALUE || intValue > Byte.MAX_VALUE) {
throw new IllegalArgumentException("Invalid input integer: " + intValue);
}

// Step 2: Convert the integer to a byte array
byte[] byteArray = new byte[4];
for (int i = 0; i < byteArray.length; i++) {
byteArray[i] = (byte) (intValue >> (i * 8));
}

// Step 3: Extend the byte vector if necessary
if (byteVector.remaining() < byteArray.length) {
byte[] newArray = new byte[byteVector.capacity() + byteArray.length];
System.arraycopy(byteVector.array(), 0, newArray, 0, byteVector.capacity());
byteVector.wrap(newArray);
}

// Step 4: Put the byte array into the byte vector
byteVector.put(byteArray);

// Step 5: Return the updated byte vector
return byteVector;
}

