    }
    if (typeVariable.getBounds() == null || typeVariable.getBounds().length == 0) {
        return Unknown.class;
    }
    return typeVariable.getBounds()[0];
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    boolean isClique = true;
    Set<V> neighbors = new HashSet<>();
    for (V vertex : vertices) {
        neighbors.addAll(graph.getNeighbors(vertex));
    }
    if (neighbors.size() != vertices.size()) {
        isClique = false;
    }
    return isClique;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the graph and the set of vertices are empty
    if (graph.isEmpty() || vertices.isEmpty()) {
        return false;
    }

    // Check if the graph and the set of vertices have the same number of elements
    if (graph.size() != vertices.size()) {
        return false;
    }

    // Check if all vertices in the graph are connected to each other
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue;
            }

            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }

    return true;
}

