}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
  // Step 1: Check if the set of vertices is empty. If it is, then the subgraph is not a clique.
  if (vertices.isEmpty()) {
    return false;
  }

  // Step 2: Check if there is only one vertex in the set. If there is, then the subgraph is a clique.
  if (vertices.size() == 1) {
    return true;
  }

  // Step 3: Get all the edges in the graph.
  Set<E> edges = graph.edgesOf(vertices);

  // Step 4: Check if there is an edge between every pair of vertices in the set.
  for (V vertex1 : vertices) {
    for (V vertex2 : vertices) {
      if (vertex1 != vertex2 && !edges.contains(graph.getEdge(vertex1, vertex2))) {
        return false;
      }
    }
  }

  // Step 5: If we reach this point, then the subgraph is a clique.
  return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
  /*
   * Step 1: Sort the keys in ascending order.
   */
  Collections.sort(keys);

  /*
   * Step 2: Initialize the lower bound for each key as the minimum value of the key.
   */
  List<Integer> lowerBounds = new ArrayList<>(keys.size());
  for (K key : keys) {
    lowerBounds.add(key.getLowerBound());
  }

  /*
   * Step 3: Update the lower bound for each key based on the lower bounds of the previous and next keys.
   */
  for (int i = 1; i < keys.size() - 1; i++) {
    K currentKey = keys.get(i);
    K previousKey = keys.get(i - 1);
    K nextKey = keys.get(i + 1);

    int currentLowerBound = lowerBounds.get(i);
    int previousLowerBound = lowerBounds.get(i - 1);
    int nextLowerBound = lowerBounds.get(i + 1);

    int minLowerBound = Math.min(currentLowerBound, Math.min(previousLowerBound, nextLowerBound));

    lowerBounds.set(i, minLowerBound);
  }

  return lowerBounds;
}

