private void pop(final String descriptor) {
    // Step 1: Parse the given descriptor to determine the number of types to pop
    String[] tokens = descriptor.split("\\s+");
    int numTypes = 0;
    for (String token : tokens) {
        if (token.equals("()")) {
            // End of method arguments
            break;
        } else if (token.equals(")")) {
            // End of method return type
            break;
        } else if (token.equals(",") || token.equals(".")) {
            // Skip separators
            continue;
        } else if (token.equals("V")) {
            // Void return type
            break;
        }
        numTypes++;
    }

    // Step 2: Pop the specified number of types from the output frame stack
    for (int i = numTypes - 1; i >= 0; i--) {
        Class<?> type = stack.pop();
        if (type == null) {
            throw new RuntimeException("Failed to pop type from stack: empty stack");
        }
    }
}

public void pop(final String descriptor) {
        if (descriptor == null) {
            throw new IllegalArgumentException("Descriptor can not be null");
        }
        if (descriptor.trim().isEmpty()) {
            throw new IllegalArgumentException("Descriptor can not be empty");
        }

        int descriptorLength = descriptor.length();
        if (descriptorLength == 1) {
            // Pop the top value from the stack
            stack.pop();
        } else {
            // Pop the values from the stack based on the descriptor
            String[] descriptorParts = descriptor.split("\\s+");
            for (String descriptorPart : descriptorParts) {
                if (descriptorPart.equals("(")) {
                    // Ignore the opening parentheses
                    continue;
                } else if (descriptorPart.equals(")")) {
                    // Pop the values from the stack based on the descriptor
                    pop(descriptorPart);
                } else {
                    // Issue a pop operation for the corresponding type
                    if (descriptorPart.equals("INT")) {
                        stack.pop(Type.INT);
                    } else if (descriptorPart.equals("FLOAT")) {
                        stack.pop(Type.FLOAT);
                    } else if (descriptorPart.equals("REF")) {
                        stack.pop(Type.REF);
                    }
                }
            }
        }
    }

public void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Invalid descriptor");
    }
    String[] types = descriptor.split(" ");

    // Pop types from the stack according to the descriptor
    for (int i = 0; i < types.length; i++) {
        if (types[i].equals("byte")) {
            pop((byte)0);
        } else if (types[i].equals("char")) {
            pop((char)0);
        } else if (types[i].equals("short")) {
            pop((short)0);
        } else if (types[i].equals("int")) {
            pop(0);
        } else if (types[i].equals("long")) {
            pop(0L);
        } else if (types[i].equals("float")) {
            pop(0.0f);
        } else if (types[i].equals("double")) {
            pop(0.0d);
        } else if (types[i].equals("reference")) {
            pop((Reference)null);
        }
    }
}

private void pop(final String descriptor) {
    // Step 1: Parse the descriptor to determine the number of types to pop
    int numTypesToPop = getNumTypesToPop(descriptor);

    // Step 2: Pop the types from the output frame stack
    Frame frame = getOutputFrame();
    for (int i = 0; i < numTypesToPop; i++) {
        frame.popType();
    }
}

