public static String applyRelativePath(String path, String relativePath) {
    // Validate input parameters
    if (path == null || path.isEmpty()) {
        throw new IllegalArgumentException("The path cannot be null or empty.");
    }
    if (relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("The relative path cannot be null or empty.");
    }

    // Normalize the path and relative path
    Path normalizedPath = Paths.get(path).normalize();
    Path normalizedRelativePath = Paths.get(relativePath).normalize();

    // Combine the two paths using the "/" separator
    String combinedPath = normalizedPath.toString() + "/" + normalizedRelativePath.toString();

    // Return the combined path
    return combinedPath;
}

public static String applyRelativePath(String path, String relativePath) {
    // Step 1: Validate input
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Input path and relative path must not be null");
    }

    // Step 2: Determine if the relative path is absolute or relative
    if (!relativePath.startsWith("/") || !relativePath.startsWith("\\")) {
        // Relative path
        // Step 3: Split the relative path into parts
        String[] parts = relativePath.split("/");

        // Step 4: Remove "." and ".." parts
        for (int i = 0; i < parts.length; i++) {
            if (parts[i].equals(".") || parts[i].equals("..")) {
                parts[i] = "";
            }
        }

        // Step 5: Join the parts back together
        String joinedPath = String.join("/", parts);

        // Step 6: Return the final path
        return path + "/" + joinedPath;
    } else {
        // Absolute path
        // Step 7: Directly return the absolute path
        return relativePath;
    }
}

public static String applyRelativePath(String path, String relativePath) {
    // Validate input
    if (path == null || path.isEmpty()) {
        throw new IllegalArgumentException("Path cannot be null or empty");
    }
    if (relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Relative path cannot be null or empty");
    }

    // Convert any Windows path separators to Unix separators
    path = path.replace("\\", "/");
    relativePath = relativePath.replace("\\", "/");

    // Remove any trailing slashes from the path and relativePath
    path = path.replaceAll("/+$", "");
    relativePath = relativePath.replaceAll("/+$", "");

    // If the relativePath starts with a slash, it is absolute
    if (relativePath.startsWith("/")) {
        return path + relativePath;
    }

    // If the relativePath starts with a dot, it is relative to the current directory
    if (relativePath.startsWith(".")) {
        return path + relativePath;
    }

    // Otherwise, the relativePath is relative to the parent directory
    return path + "/../" + relativePath;
}

public static String applyRelativePath(String path, String relativePath) {
    // Ensure that the path and relative path are not null or empty
    if (path == null || path.isEmpty()) {
        throw new IllegalArgumentException("Path must not be null or empty.");
    }
    if (relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Relative path must not be null or empty.");
    }

    // Split the path and relative path into their component folders
    String[] pathFolders = path.split("/");
    String[] relativePathFolders = relativePath.split("/");

    // Iterate through the relative path folders and update the path accordingly
    for (String folder : relativePathFolders) {
        if (folder.equals("..")) {
            if (pathFolders.length > 0) {
                pathFolders = Arrays.copyOfRange(pathFolders, 0, pathFolders.length - 1);
            }
        } else if (folder.equals(".")) {
            // Do nothing
        } else {
            pathFolders = Arrays.copyOf(pathFolders, pathFolders.length + 1);
            pathFolders[pathFolders.length - 1] = folder;
        }
    }

    // Join the updated path folders with "/" separators and return the result
    return String.join("/", pathFolders);
}

public static String applyRelativePath(String path, String relativePath) {
    // Check if the path is valid
    if (path == null || path.isEmpty()) {
        throw new IllegalArgumentException("Path cannot be null or empty");
    }

    // Check if the relative path is valid
    if (relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Relative path cannot be null or empty");
    }

    // Remove any leading or trailing slashes from the relative path
    relativePath = relativePath.replaceAll("^/+|/+$", "");

    // Split the relative path into its components
    String[] components = relativePath.split("/");

    // Check if the relative path is absolute
    if (relativePath.startsWith("/")) {
        // The relative path is absolute, so we need to remove the leading slash
        // and add the components to the path
        path = path.substring(0, path.length() - 1);
        for (String component : components) {
            path += "/" + component;
        }
    } else {
        // The relative path is relative, so we need to add the components to the path
        for (String component : components) {
            path += "/" + component;
        }
    }

    // Return the full file path that results from applying the relative path
    return path;
}

