}

public Edge edgeToNext(){
  if(currentNode.isVirtual()){
    // if the current node is virtual, return an edge to its real counterpart
    return new Edge(virtualToRealMap.get(currentNode), virtualToRealMap.get(nextNode));
  } else {
    // if the current node is real, return an edge from it to the next node
    return new Edge(currentNode, nextNode);
  }
}

public Edge edgeToNext() {
    // Check if either of the nodes is virtual
    if (this.isVirtual || this.next.isVirtual) {
        // If either node is virtual, get its real counterpart
        Node realThis = this.isVirtual ? this.getRealNode() : this;
        Node realNext = this.next.isVirtual ? this.next.getRealNode() : this.next;

        // Create the edge between the real nodes
        Edge edge = new Edge(realThis, realNext);

        return edge;
    } else {
        // Both nodes are real, so create the edge between them
        Edge edge = new Edge(this, this.next);

        return edge;
    }
}

