public final ByteVector put11(final int byteValue1, final int byteValue2) {
    // Step 1: Check if the byte vector is null
    if (this == null) {
        throw new NullPointerException("Byte vector cannot be null");
    }

    // Step 2: Check if the byte values are valid
    if (byteValue1 < 0 || byteValue1 > 255 || byteValue2 < 0 || byteValue2 > 255) {
        throw new IllegalArgumentException("Byte values must be between 0 and 255");
    }

    // Step 3: Enlarge the byte vector if necessary
    if (this.length + 2 > this.data.length) {
        this.ensureCapacity(this.length + 2);
    }

    // Step 4: Put the bytes into the byte vector
    this.data[this.length++] = (byte) byteValue1;
    this.data[this.length++] = (byte) byteValue2;

    return this;
}

public final ByteVector put11(final int byteValue1, final int byteValue2) {
    // Step 1: Check if the byte vector is full
    if (this.size + 2 > this.data.length) {
        // If the byte vector is full, create a new array with double the size and copy the current elements
        byte[] newData = new byte[this.data.length * 2];
        System.arraycopy(this.data, 0, newData, 0, this.size);
        this.data = newData;
    }

    // Step 2: Put the two bytes into the byte vector
    this.data[this.size++] = (byte) byteValue1;
    this.data[this.size++] = (byte) byteValue2;

    return this;
}

