public ByteVector put11(int byteValue1, int byteValue2) {
  // Check if the vector is large enough to hold the two bytes
  if (this.data == null || this.data.length - this.length < 2) {
    // If not, resize the vector
    byte[] newData = new byte[Math.max(this.length, 2)];
    // Copy the current data to the new vector
    if (this.length > 0) {
      System.arraycopy(this.data, 0, newData, 0, this.length);
    }
    // Set the new data and length
    this.data = newData;
    this.length = Math.max(this.length, 2);
  }

  // Put the two bytes at the end of the vector
  byteValue1 &= 0xFF;
  byteValue2 &= 0xFF;
  this.data[this.length] = byteValue1;
  this.data[this.length + 1] = byteValue2;
  this.length += 2;

  return this;
}

