public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshotList = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        for (String line; (line = reader.readLine()) != null; ) {
            // Parse the line
            String[] parts = line.split("\\s+");
            if (parts.length < 2) {
                throw new IOException("Invalid line format: " + line);
            }
            long time = Long.parseLong(parts[0]);
            long threadId = Long.parseLong(parts[1]);
            String threadName = parts[2];
            String status = parts.length > 3 ? parts[3] : null;
            List<TraceEvent> traceEvents = new ArrayList<>();
            for (int i = 0; i < parts.length; i += 2) {
                long traceId = Long.parseLong(parts[i]);
                long startTime = Long.parseLong(parts[i + 1]);
                long endTime = Long.parseLong(parts[i + 2]);
                traceEvents.add(new TraceEvent(traceId, startTime, endTime));
            }
            ThreadSnapshot snapshot = new ThreadSnapshot(time, threadId, threadName, status, traceEvents);
            snapshotList.add(snapshot);
        }
    } catch (IOException e) {
        throw new IOException("Error parsing thread snapshots from file", e);
    }
    return snapshotList;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

	List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
	ProfileAnalyzeTimeRange timeRange = new ProfileAnalyzeTimeRange();
	FileReader fileReader = new FileReader(file);
	BufferedReader bufferedReader = new BufferedReader(fileReader);
	String currentLine;
	while ((currentLine = bufferedReader.readLine()) != null) {
		String[] lineParts = currentLine.split(",");
		if (lineParts.length != 4) {
			throw new IOException("Invalid line length in file");
		}
		String threadName = lineParts[0];
		long timeStamp = Long.parseLong(lineParts[1]);
		ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadName, timeStamp);
		threadSnapshots.add(threadSnapshot);
	}
	bufferedReader.close();
	fileReader.close();
	return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Step 1: Read the file and parse the contents into a list of ThreadSnapshot objects
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            threadSnapshots.add(parseThreadSnapshot(line));
        }
    }

    // Step 2: Loop through the thread snapshots and filter out the ones that fall outside the given time range
    // The time range is passed as a list of ProfileAnalyzeTimeRange objects
    List<ThreadSnapshot> filteredThreadSnapshots = new ArrayList<>();
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        for (ThreadSnapshot threadSnapshot : threadSnapshots) {
            if (threadSnapshot.getStartTime() >= timeRange.getStartTime() && threadSnapshot.getEndTime() <= timeRange.getEndTime()) {
                filteredThreadSnapshots.add(threadSnapshot);
            }
        }
    }

    return filteredThreadSnapshots;
}

private static ThreadSnapshot parseThreadSnapshot(String line) {
    // Assuming the line is in the format "thread_id, start_time, end_time, thread_name, thread_state"
    String[] parts = line.split(", ");
    long threadId = Long.parseLong(parts[0]);
    long startTime = Long.parseLong(parts[1]);
    long endTime = Long.parseLong(parts[2]);
    String threadName = parts[3];
    Thread.State threadState = Thread.State.valueOf(parts[4]);
    return new ThreadSnapshot(threadId, startTime, endTime, threadName, threadState);
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    Objects.requireNonNull(file, "File cannot be null");
    Objects.requireNonNull(timeRanges, "Time ranges cannot be null");

    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot threadSnapshot = ThreadSnapshot.parseFrom(line);
            if (threadSnapshot != null) {
                threadSnapshots.add(threadSnapshot);
            }
        }
    }

    List<ThreadSnapshot> filteredThreadSnapshots = threadSnapshots.stream()
            .filter(threadSnapshot -> threadSnapshot.getTimestamp() >= timeRanges.get(0).getStartTime() &&
                    threadSnapshot.getTimestamp() <= timeRanges.get(timeRanges.size() - 1).getEndTime())
            .collect(Collectors.toList());

    return filteredThreadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

    if (file == null || timeRanges == null) {
        throw new IllegalArgumentException("File or time ranges cannot be null");
    }

    // create a new CSV parser for the file
    CSVParser parser = new CSVParser(new FileReader(file));

    // create a new list to store the thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    for (CSVRecord record : parser) {
        // get the timestamp for the current record
        long timestamp = Long.parseLong(record.get(0));

        // check if the timestamp is within any of the specified time ranges
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (timeRange.contains(timestamp)) {
                // create a new thread snapshot from the current record
                ThreadSnapshot threadSnapshot = new ThreadSnapshot(record);
                // add the thread snapshot to the list
                threadSnapshots.add(threadSnapshot);
                break;
            }
        }
    }

    // close the parser
    parser.close();

    return threadSnapshots;
}
